
// This file was generated by Prisma and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

// Plain `process.env.DATABASE_URL` (undefined if unset) instead of the
// `env()` helper, which throws eagerly if the var is missing — and
// commands that actually need a connection (migrate deploy) errored
// oddly if `datasource` was left out of this config entirely. This way
// `prisma generate` (our postinstall script) still works with no
// DATABASE_URL at all, e.g. during `npm install` before env vars are
// configured on a fresh Vercel project, while commands that need a real
// connection get schema.prisma's own clear "env var not found" error
// instead of a config-load crash.
export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
    seed: "tsx prisma/seed.ts",
  },
  engine: "classic",
  datasource: {
    url: process.env.DATABASE_URL,
  },
});
